  producer: Building,
  resource: ResourceType,
  buildings: readonly Building[],
  inventory: DeliveryInventoryPort,
  routes: DeliveryRoutePort,
): RouteCandidate | null {
  if (!isStorableResource(resource)) return null;
  // C4 (AL-2, decision AL4): barley waits in its barn for the kiln to fetch it; it never fills the granaries' room.
  if (resource === "barley") return null;
  // Stock another carter already claimed (a mill fetching from a barn, AF-9) stays for that carter.
  const stock = Math.min(amountOf(producer.inventory, resource), inventory.availableStock(producer, resource));
  if (stock === 0) return null;
  const storeKind = STORAGE_KIND_BY_RESOURCE[resource];
  // C5 (CL-4…CL-7, decision CL6): cloth passes from hand to hand — each stage's cart takes it to the next stage's
  // building while that one has room, and only then to a storehouse (the stores of a grown town stand full of timber).
  const next = CLOTH_NEXT_STAGE[resource];
  if (next !== undefined) {
    const direct = buildings.flatMap((building) => {
      if (building.kind !== next || building.id === producer.id) return [];
      const path = routes.betweenBuildings(producer.id, building.id);
      if (path === null || path.length === 0) return [];
      // F4-A (decision RG4): the cart leaves the dyehouse room for the dyes it holds — a vat full of fulled cloth took no
      // dyes and the chain stood (the probe of the chapter-4 town, 1377).
      const dyeRoom = building.kind === "dyehouse" ? Math.max(0, CLOTH_BALANCE.dyesHeld - amountOf(building.inventory, "dyes")) : 0;
      const amount = Math.min(BUILDING_CONFIG_BY_KIND[producer.kind].carterCapacity ?? BALANCE.CARTER_CAPACITY, stock, inventory.availableSpace(building) - dyeRoom);
      return amount > 0 ? [{ building, path, amount }] : [];
    });
    const best = bestCandidate(direct, false);
    if (best !== null) return best;
  }
  const candidates = buildings.flatMap((building) => {
    if (building.kind !== storeKind) return [];
    const path = routes.betweenBuildings(producer.id, building.id);
    if (path === null || path.length === 0) return [];
    const amount = Math.min(
      BUILDING_CONFIG_BY_KIND[producer.kind].carterCapacity ?? BALANCE.CARTER_CAPACITY,
      stock,
      storageIntakeSpace(building, resource, inventory.availableSpace(building)),
    );
    return amount > 0 ? [{ building, path, amount }] : [];
  });
  return bestCandidate(candidates, resource === "bread");
}

export function fetchCandidate(
  converter: Building,
  resource: ResourceType,
  buildings: readonly Building[],
  inventory: DeliveryInventoryPort,
  routes: DeliveryRoutePort,
): RouteCandidate | null {
  if (!isStorableResource(resource)) return null;
  const homeSpace = inventory.availableSpace(converter);
  if (homeSpace === 0) return null;
  const storeKind = STORAGE_KIND_BY_RESOURCE[resource];
  // AF-9: a mill also fetches wheat straight from a farmstead's barn. When no store or barn holds the input, a
  // converter fetches it from the producer that makes it (a sawmill from a logging camp), so a store full of other
  // goods cannot stop a chain.
  const from = (accepts: (building: Building) => boolean) => buildings.flatMap((building) => {
    if (!accepts(building)) return [];
    const path = routes.betweenBuildings(converter.id, building.id);
    if (path === null || path.length === 0) return [];
    const amount = Math.min(
      BUILDING_CONFIG_BY_KIND[converter.kind].carterCapacity ?? BALANCE.CARTER_CAPACITY,
      homeSpace,
      inventory.availableStock(building, resource),
    );
    return amount > 0 ? [{ building, path, amount }] : [];
  });
  const stored = from(building => building.kind === storeKind || barnHolds(building, resource));
  // LB-15 (BOT-3): while a barn is piled with the input the other barns drop out; stores keep their place.
  const barn = (building: Building) => barnHolds(building, resource);
  const piled = (building: Building) => barn(building) && amountOf(building.inventory, resource) >= BARN_BACKLOG_STOCK;
  const drawn = stored.some(({ building }) => piled(building)) ? stored.filter(({ building }) => !barn(building) || piled(building)) : stored;
  const candidates = drawn.length > 0 ? drawn
    : from(building => building.id !== converter.id && BUILDING_CONFIG_BY_KIND[building.kind].production?.output === resource);
  const production = BUILDING_CONFIG_BY_KIND[converter.kind].production;
  const physical = amountOf(converter.inventory, resource);
  const usable = inventory.availableStock(converter, resource);
  if (production?.input === resource && Number.isFinite(production.inputPerOutput)
    && production.inputPerOutput > 0 && Number.isFinite(physical) && physical >= 0
    && Number.isFinite(usable) && usable === physical) {
    const deficit = production.inputPerOutput - physical;
    if (deficit > 0) {
      const sufficient = candidates.filter(({ amount }) => amount >= deficit);
      if (sufficient.length > 0) return bestCandidate(sufficient);
    }
  }
  return bestCandidate(candidates);
}

  readonly tick: number;
  readonly building: Building;
  readonly buildings: readonly Building[];
  readonly inputResource: ResourceType;
  readonly inventory: DeliveryInventoryPort;
  readonly routes: DeliveryRoutePort;
  readonly cart?: CarterWalker["cart"];
}): { readonly buildings: readonly Building[]; readonly walker: CarterWalker | null } {
  const candidate = fetchCandidate(
    params.building,
    params.inputResource,
    params.buildings,
    params.inventory,
    params.routes,
  );
  if (candidate === null) return { buildings: params.buildings, walker: null };
  const reservedHome = params.inventory.reserveSpace(
    params.building,
    params.inputResource,
    candidate.amount,
  );
  const reservedSource = params.inventory.reserveStock(
    candidate.building,
    params.inputResource,
    candidate.amount,
  );
  const claim = amountOf(reservedSource.stockReserved, params.inputResource) -
    amountOf(candidate.building.stockReserved, params.inputResource);
  if (claim === 0) return { buildings: params.buildings, walker: null };
  const buildings = replaceBuilding(
    replaceBuilding(params.buildings, reservedHome),
    reservedSource,
  );
  return {
    buildings,
    walker: spawnCarter({
      tick: params.tick,
      home: reservedHome,
      destination: { kind: "building", buildingId: reservedSource.id },
      path: candidate.path,
      mission: "fetch",
      cargo: null,
      ...(params.cart === undefined ? {} : { cart: params.cart }),
      reservation: {
        destination: { kind: "building", buildingId: reservedHome.id },
        resource: params.inputResource,
        amount: claim,
        sourceStockClaim: {
          kind: "building",
          buildingId: reservedSource.id,
          resource: params.inputResource,
          amount: claim,
        },
        homeCapacityClaim: null,
      },
    }),
  };
}

function spawnDelivery(params: {
  readonly tick: number;
  readonly building: Building;
  readonly buildings: readonly Building[];
  readonly outputResource: ResourceType;
  readonly inventory: DeliveryInventoryPort;
  readonly routes: DeliveryRoutePort;
  readonly candidate?: RouteCandidate | null;
  readonly cart?: CarterWalker["cart"];
}): { readonly buildings: readonly Building[]; readonly walker: CarterWalker | null } {
  const candidate = params.candidate !== undefined ? params.candidate : deliverCandidate(
    params.building,
    params.outputResource,
    params.buildings,
    params.inventory,
    params.routes,
  );
  if (candidate === null) return { buildings: params.buildings, walker: null };
  const loadedHome = withStock(
    params.building,
    params.outputResource,
    amountOf(params.building.inventory, params.outputResource) - candidate.amount,
  );
  const reservedHome = params.inventory.reserveSpace(
    loadedHome,
    params.outputResource,
    candidate.amount,
  );
  const homeClaim =
    amountOf(reservedHome.reserved, params.outputResource) -
    amountOf(loadedHome.reserved, params.outputResource);
  if (homeClaim !== candidate.amount) {
    return { buildings: params.buildings, walker: null };
  }
  const reservedDestination = params.inventory.reserveSpace(
    candidate.building,
    params.outputResource,
    candidate.amount,
  );
  const buildings = replaceBuilding(
    replaceBuilding(params.buildings, reservedHome),
    reservedDestination,
  );
  return {
    buildings,
    walker: spawnCarter({
      tick: params.tick,
      home: reservedHome,
      destination: { kind: "building", buildingId: reservedDestination.id },
      path: candidate.path,
      mission: "deliver",
      cargo: { resource: params.outputResource, amount: candidate.amount },
      ...(params.cart === undefined ? {} : { cart: params.cart }),
      reservation: {
        destination: { kind: "building", buildingId: reservedDestination.id },
        resource: params.outputResource,
        amount: candidate.amount,
        sourceStockClaim: null,
        homeCapacityClaim: {
          buildingId: reservedHome.id,
          resource: params.outputResource,
          amount: homeClaim,
        },
      },
    }),
  };
}

function spawnForBuilding(
  tick: number,
  building: Building,
  buildings: readonly Building[],
  inventory: DeliveryInventoryPort,
  routes: DeliveryRoutePort,
): { readonly buildings: readonly Building[]; readonly walker: CarterWalker | null } {
  const definition = BUILDING_CONFIG_BY_KIND[building.kind];
  const production = definition.production;
  // AF-9: a farmstead's carter hauls the harvest from its barn like production output.
  if (production === null) {
    // C5 (CL-2): a pastoral farm's carter hauls the shorn fleece from its yard.
    if (definition.yardOutput !== undefined) return spawnDelivery({ tick, building, buildings, outputResource: definition.yardOutput, inventory, routes });
    const field = fieldOutputResource(building);
    return field === undefined ? { buildings, walker: null }
      : spawnDelivery({ tick, building, buildings, outputResource: field, inventory, routes });
  }
  if (building.kind === "mill" && amountOf(building.inventory, production.output) >= BALANCE.CARTER_CAPACITY) {
    const delivery = spawnDelivery({ tick, building, buildings, outputResource: production.output, inventory, routes });
    if (delivery.walker !== null) return delivery;
  }
  // LB-7: a mill's wheat comes by its intake cart and granary pushes; its main cart only takes bread out.
  if (
    production.input !== null && building.kind !== "mill" &&
    amountOf(building.inventory, production.input) < production.inputPerOutput
  ) {
    const fetch = spawnFetch({
      tick,
      building,
      buildings,
      inputResource: production.input,
      inventory,
      routes,
    });
    if (fetch.walker !== null) return fetch;
  }
  return spawnDelivery({
    tick,
    building,
    buildings,
    outputResource: production.output,
    inventory,
    routes,
  });
}

/** LB-7: wheat a mill holds plus wheat already on its way (reserved space). */
function millWheat(mill: Building): number {
  return amountOf(mill.inventory, "wheat") + amountOf(mill.reserved, "wheat");
}

/** LB-7: the mill in a granary's reach that most needs wheat (least held + incoming, then route, then id). */
function pushCandidate(granary: Building, buildings: readonly Building[], inventory: DeliveryInventoryPort, routes: DeliveryRoutePort): RouteCandidate | null {
  const stock = Math.min(amountOf(granary.inventory, "wheat"), inventory.availableStock(granary, "wheat"));
  if (stock === 0) return null;
  const candidates = buildings.flatMap((mill) => {
    if (!pushableMill(granary, mill) || millWheat(mill) >= LABOUR_BALANCE.millPushTarget) return [];
    const space = inventory.availableSpace(mill);
    if (space === 0) return [];
    const path = routes.betweenBuildings(granary.id, mill.id);
    if (path === null || path.length === 0) return [];
    return [{ building: mill, path, amount: Math.min(LABOUR_BALANCE.millCartCapacity, stock, space) }];
  });
  return [...candidates].sort((left, right) => millWheat(left.building) - millWheat(right.building)
    || left.path.length - right.path.length || left.building.id.localeCompare(right.building.id))[0] ?? null;
}

/** LB-7: mills' intake carts, then granary pushes (a granary needs a hauler from the day pool), after the main carts. */
function spawnSecondCarts(input: DeliveryStepInput, start: readonly Building[], walkers: Walker[]): readonly Building[] {
  let buildings = start;
  const intake = activeCarterHomes(walkers, "intake");
  for (const mill of [...start].filter(building => building.kind === "mill").sort(byId)) {
    const current = buildings.find(({ id }) => id === mill.id) ?? mill;
    if (intake.has(mill.id) || operationSuspended(current) || millWheat(current) >= LABOUR_BALANCE.millWheatTarget) continue;
    const fetched = spawnFetch({ tick: input.tick, building: current, buildings, inputResource: "wheat",
      inventory: input.inventory, routes: input.routes, cart: "intake" });
    if (fetched.walker === null) continue;
    buildings = fetched.buildings;
    walkers.push(fetched.walker);
  }
  const pushing = activeCarterHomes(walkers, "push");
  for (const granary of [...start].filter(building => building.kind === "granary" && (building.haulers ?? 0) > 0).sort(byId)) {
    const current = buildings.find(({ id }) => id === granary.id) ?? granary;
    if (pushing.has(granary.id) || operationSuspended(current)) continue;
    const candidate = pushCandidate(current, buildings, input.inventory, input.routes);
    if (candidate === null) continue;
    const pushed = spawnDelivery({ tick: input.tick, building: current, buildings, outputResource: "wheat",
      inventory: input.inventory, routes: input.routes, candidate, cart: "push" });
    if (pushed.walker === null) continue;
    buildings = pushed.buildings;
    walkers.push(pushed.walker);
  }
  return buildings;
}

export function spawnCarters(input: DeliveryStepInput): DeliveryStepResult {
  let constructionSites = input.constructionSites ?? [];
  let treasuryTimber = input.treasuryTimber ?? 0;
  const walkers: Walker[] = [...input.walkers];
  let buildings = input.buildings;
  const busyHomes = activeCarterHomes(walkers);

  if (constructionSites.length > 0) {
    for (const building of [...buildings].sort(byId)) {
      if (busyHomes.has(building.id)) continue;
      const production = BUILDING_CONFIG_BY_KIND[building.kind].production;
      if (production === null || production.input === null || building.kind === "mill" ||
          amountOf(building.inventory, production.input) >= production.inputPerOutput) continue;
      const fetched = spawnFetch({
        tick: input.tick,
        building,
        buildings,
        inputResource: production.input,
        inventory: input.inventory,
        routes: input.routes,
      });
      if (fetched.walker === null) continue;
      buildings = fetched.buildings;
      walkers.push(fetched.walker);
      input.materialActivity?.({ kind: "dispatch", tick: input.tick, walker: fetched.walker });
      busyHomes.add(building.id);
    }
  }

  const siteDispatch = spawnSiteDelivery({
    tick: input.tick,
    buildings,
    constructionSites,
    treasuryTimber,
    inventory: input.inventory,
    routes: input.routes,
    busyHomeIds: busyHomes,
    ...(input.wallConstructionReserve === undefined ? {} : { wallConstructionReserve: input.wallConstructionReserve }),
    ...(input.wallConstructionPriority === undefined ? {} : { wallConstructionPriority: input.wallConstructionPriority }),
  });
  const siteWalker = siteDispatch?.walkers[0] ?? null;
  if (siteDispatch !== null && siteWalker !== null && !busyHomes.has(siteWalker.homeBuildingId)) {
    buildings = siteDispatch.buildings;
    constructionSites = siteDispatch.constructionSites;
    treasuryTimber = siteDispatch.treasuryTimber;
    walkers.push(siteWalker);
    if (siteWalker.kind === "carter") input.materialActivity?.({ kind: "dispatch", tick: input.tick, walker: siteWalker });
    busyHomes.add(siteWalker.homeBuildingId);
  }

  for (const building of [...buildings].sort(byId)) {
    if (busyHomes.has(building.id)) continue;
    const current = buildings.find(({ id }) => id === building.id) ?? building;
    const result = spawnForBuilding(
      input.tick,
      current,
      buildings,
      input.inventory,
      input.routes,
    );
    buildings = result.buildings;
    if (result.walker !== null) {
      walkers.push(result.walker);
      input.materialActivity?.({ kind: "dispatch", tick: input.tick, walker: result.walker });
      busyHomes.add(building.id);
    }
  }

  // LB-7: second carts go after every main cart, so producers and barns keep first claim on their own stock.
  buildings = spawnSecondCarts(input, buildings, walkers);
  return { buildings, constructionSites, walkers: walkers.sort(byId), treasuryTimber };
}

  buildings: readonly Building[],
  carter: CarterWalker,
  routes: DeliveryRoutePort,
): boolean {
  if (!remainingPathCanBeTraversed(carter, routes.canTraverse)) return false;
  const endpoint = carter.path.at(-1);
  const destination = carter.phase === "outbound" ? carter.destination
    : { kind: "building" as const, buildingId: carter.homeBuildingId };
  if (endpoint !== undefined && routes.canAccessDestination?.(endpoint, destination) === false) return false;
  const remainingPathIsRoad = carter.path
    .slice(Math.max(0, carter.pathIndex))
    .every((tile) => routes.isRoad(tile)
      || routes.canCarryForDestination?.(tile, carter.destination) === true);
  if (!remainingPathIsRoad || carter.phase !== "outbound") {
    return remainingPathIsRoad;
  }

  return returnPath(buildings, carter, routes) !== null;
}

export function stepCarters(input: DeliveryStepInput): DeliveryStepResult {
  let buildings = input.buildings;
  let constructionSites = input.constructionSites ?? [];
  let treasuryTimber = input.treasuryTimber ?? 0;
  const walkers: Walker[] = [];

  for (const walker of [...input.walkers].sort((a, b) => a.id.localeCompare(b.id))) {
    if (walker.kind !== "carter") {
      walkers.push(walker);
      continue;
    }
    if (walker.cancellation !== null) input.materialActivity?.({ kind: 'cancelled', tick: input.tick, homeId: walker.homeBuildingId, walkerId: walker.id });
    if (
      walker.phase === "returning" &&
      walker.cancellation !== null &&
      hasArrivedAtPathEnd(walker)
    ) {
      if (!canCompleteReturn(buildings, walker, input.inventory)) {
        walkers.push(walker);
        continue;
      }
      const returned = completeReturn(
        { buildings, constructionSites, treasuryTimber },
        walker,
        input.inventory,
      );
      observeMaterialReturn(input, walker);
      buildings = returned.buildings;
      constructionSites = returned.constructionSites;
      treasuryTimber = returned.treasuryTimber;
      continue;
    }
    if (!routeIsIntact(buildings, walker, input.routes)) {
      input.materialActivity?.({ kind: "cancelled", tick: input.tick, homeId: walker.homeBuildingId, walkerId: walker.id });
      const cancelled = cancelCarter(
        input.tick,
        { buildings, constructionSites, treasuryTimber },
        walker,
        input.inventory,
        input.routes,
        "road_removed",
      );
      buildings = cancelled.buildings;
      constructionSites = cancelled.constructionSites;
      treasuryTimber = cancelled.treasuryTimber;
      if (cancelled.walker !== null) walkers.push(cancelled.walker);
      continue;
    }

    const from = walker.path[walker.pathIndex];
    const to = walker.path[walker.pathIndex + 1];
    const carry = walker.destination.kind === 'construction_site' && from !== undefined && to !== undefined
      && (!input.routes.isRoad(from) || !input.routes.isRoad(to))
      && input.routes.canCarryForDestination?.(to, walker.destination) === true;
    const length = from === undefined || to === undefined ? 1
      : Math.abs(from.tx - to.tx) + Math.abs(from.ty - to.ty);
    // FIX-10 (FD-2): wading a ford is slower.
    const speed = wadingPace(input.routes.isFord, from, to, carry && length > 0 ? BALANCE.CARTER_SPEED / WALL_CARRY_COST_FACTOR : BALANCE.CARTER_SPEED);
    const moved = stepWalkerAlongPath(walker, speed);
    if (!hasArrivedAtPathEnd(moved)) {
      walkers.push(moved);
      continue;
    }
    if (moved.phase === "returning") {
      if (!canCompleteReturn(buildings, moved, input.inventory)) {
        walkers.push(moved);
        continue;
      }
      const returned = completeReturn(
        { buildings, constructionSites, treasuryTimber },
        moved,
        input.inventory,
      );
      observeMaterialReturn(input, moved);
      buildings = returned.buildings;
      constructionSites = returned.constructionSites;
      treasuryTimber = returned.treasuryTimber;
      continue;
    }

    const completed = completeOutbound(
      { buildings, constructionSites, treasuryTimber },
      moved,
      input,
    );
    buildings = completed.buildings;
    constructionSites = completed.constructionSites;
    treasuryTimber = completed.treasuryTimber;
    if (completed.walker !== null) walkers.push(completed.walker);
  }

  return { buildings, constructionSites, walkers, treasuryTimber };
}

function completeDelivery(
  state: DeliveryResourceState,
  carter: CarterWalker,
  inventory: DeliveryInventoryPort,
  routes: DeliveryRoutePort,
  tick: number,
  materialActivity?: DeliveryStepInput["materialActivity"],
  buildingDelivery?: DeliveryStepInput["buildingDelivery"],
): CarterResult {
  if (carter.reservation.destination.kind === "construction_site") {
    const site = findSite(
      state.constructionSites,
      carter.reservation.destination.siteId,
    );
    if (site === null || carter.cargo === null) {
      return cancelCarter(
        tick,
        state,
        carter,
        inventory,
        routes,
        "destination_unavailable",
      );
    }
    if (site.kind === "stone_wall_segment" && carter.cargo.resource === "stone" && carter.cancellation === null) materialActivity?.({ kind: "wall_delivery", tick, homeId: carter.homeBuildingId, walkerId: carter.id, wallId: site.wallId, siteId: site.id, amount: carter.cargo.amount });
    const nextState = {
      ...state,
      constructionSites: replaceSite(
        state.constructionSites,
        deliverSiteResource(site, carter.cargo.resource, carter.cargo.amount),
      ),
    };
    return beginReturn(
      nextState,
      { ...carter, reservation: { ...carter.reservation, homeCapacityClaim: null } },
      null,
      inventory,
      routes,
    );
  }
  const destination = findBuilding(
    state.buildings,
    carter.reservation.destination.buildingId,
  );
  if (destination === null || carter.cargo === null) {
    return cancelCarter(
      tick,
      state,
      carter,
      inventory,
      routes,
      "destination_unavailable",
    );
  }
  const deposited = deposit(
    destination,
    carter.cargo.resource,
    carter.cargo.amount,
  );
  buildingDelivery?.({ homeBuildingId: carter.homeBuildingId, destinationBuildingId: destination.id,
    resource: carter.cargo.resource, amount: carter.cargo.amount });
  const released = inventory.releaseSpace(
    deposited,
    carter.reservation.resource,
    carter.reservation.amount,
  );
  const nextBuildings = replaceBuilding(state.buildings, released);
  const home = findBuilding(nextBuildings, carter.homeBuildingId);
  const claim = home === null ? null : returnCapacityClaim(carter, home);
  const releasedHome = home === null || claim === null
    ? nextBuildings
    : replaceBuilding(
        nextBuildings,
        inventory.releaseSpace(home, claim.resource, claim.amount),
      );
  return beginReturn(
    {
      ...state,
      buildings: releasedHome,
    },
    {
      ...carter,
      reservation: { ...carter.reservation, homeCapacityClaim: null },
    },
    null,
    inventory,
    routes,
  );
}

function completeFetch(
  state: DeliveryResourceState,
  carter: CarterWalker,
  inventory: DeliveryInventoryPort,
  routes: DeliveryRoutePort,
  tick: number,
): CarterResult {
  const claim = carter.reservation.sourceStockClaim;
  if (claim === null) {
    return cancelCarter(
      tick,
      state,
      carter,
      inventory,
      routes,
      "source_unavailable",
    );
  }
  if (claim.kind === "treasury") {
    return beginReturn(
      state,
      carter,
      { resource: "timber", amount: claim.amount },
      inventory,
      routes,
    );
  }
  const source = findBuilding(state.buildings, claim.buildingId);
  if (source === null) {
    return cancelCarter(
      tick,
      state,
      carter,
      inventory,
      routes,
      "source_unavailable",
    );
  }

  const withdrawn = inventory.withdrawStock(source, claim.resource, claim.amount);
  if (withdrawn.withdrawn === 0) {
    return cancelCarter(
      tick,
      state,
      carter,
      inventory,
      routes,
      "source_unavailable",
    );
  }
  const cleared = inventory.releaseStock(
    withdrawn.building,
    claim.resource,
    claim.amount - withdrawn.withdrawn,
  );
  const nextState = { ...state, buildings: replaceBuilding(state.buildings, cleared) };
  return beginReturn(
    nextState,
    carter,
    { resource: claim.resource, amount: withdrawn.withdrawn },
    inventory,
    routes,
  );
}

export function completeOutbound(
  state: DeliveryResourceState,
  carter: CarterWalker,
  input: DeliveryStepInput,
): CarterResult {
  return carter.mission === "deliver"
    ? completeDelivery(
        state,
        carter,
        input.inventory,
        input.routes,
        input.tick,
        input.materialActivity,
        input.buildingDelivery,
      )
    : completeFetch(
        state,
        carter,
        input.inventory,
        input.routes,
        input.tick,
      );
}

export function completeReturn(
  state: DeliveryResourceState,
  carter: CarterWalker,
  inventory: DeliveryInventoryPort,
): DeliveryResourceState {
  const claim = carter.reservation.sourceStockClaim;
  if (claim?.kind === "treasury" && carter.cargo !== null) {
    return {
      ...state,
      treasuryTimber: state.treasuryTimber + carter.cargo.amount,
    };
  }
  const home = findBuilding(state.buildings, carter.homeBuildingId);
  if (home === null) return state;
  const stocked = carter.cargo === null
    ? home
    : deposit(home, carter.cargo.resource, carter.cargo.amount);
  const capacityClaim = returnCapacityClaim(carter, home);
  const released = capacityClaim === null
    ? stocked
    : inventory.releaseSpace(stocked, capacityClaim.resource, capacityClaim.amount);
  return { ...state, buildings: replaceBuilding(state.buildings, released) };
}

